INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (213, 1, '함수의 인자와 종료 코드', '`greet() { echo "hi $1 ($#)"; return 3; }` 를 정의하고 `greet bob x` 를 실행하면 무엇이 출력되고, 바로 `echo $?` 를 하면 무엇이 나올까요?', '함수 안에서도 $1, $# 를 써요.', NULL, NULL, '[]', 'choice', '["`hi bob x (2)` 가 출력되고 `echo $?` 는 `0` 이다", "`hi  (0)` 이 출력되고 `echo $?` 는 `3` 이다", "`hi bob (2)` 가 출력되고 `echo $?` 는 `3` 이다. 함수 안의 `$1` 은 첫 번째 인자, `$#` 은 인자 개수이고 `return` 값이 종료 코드가 된다", "`hi bob (1)` 이 출력되고 `echo $?` 는 `2` 이다"]', 2, '인자 없이 `greet` 만 실행하면 `hi  (0)` 이 출력되고 종료 코드는 그대로 `3` 입니다.', NULL, NULL, NULL, NULL),
  (213, 2, '함수의 local 변수', '전역 변수 `x=global` 이 있습니다. 함수 안에서 `local x=inner` 로 바꾼 뒤 함수가 끝나면 밖의 `x` 는 무엇일까요? `local` 없이 함수 안에서 `x=changed` 를 하면요?', 'local 은 함수 안에서만 살아요.', NULL, NULL, '[]', 'choice', '["`local` 을 써도 밖의 `x` 가 `inner` 로 바뀐다", "`local x=inner` 는 함수 안에서만 쓰이므로 밖의 `x` 는 `global` 그대로이고, `local` 없이 `x=changed` 를 하면 밖의 `x` 도 `changed` 로 바뀐다", "`local` 이 없으면 함수 안에서 `x` 를 바꿀 수 없다", "함수가 끝나면 `x` 는 삭제되어 비어 있다"]', 1, '`local` 없이 함수 안에서 처음 만든 변수도 함수가 끝난 뒤에 남아 있습니다.', NULL, NULL, NULL, NULL),
  (213, 3, '$(( )) 산술', '`echo $((7/3)) $((7%3)) $((2**10))` 은 무엇을 출력할까요?', 'bash 산술은 정수 계산이에요.', NULL, NULL, '[]', 'choice', '["`2 1 1024` 가 출력된다. `/` 는 소수점 없이 몫만, `%` 는 나머지, `**` 는 거듭제곱이다", "`2.33 1 100` 이 출력된다", "`2 3 20` 이 출력된다", "`7/3 7%3 2**10` 이 그대로 출력된다"]', 0, '`a=$((a+1))` 처럼 변수에 계산 결과를 넣을 수 있습니다.', NULL, NULL, NULL, NULL),
  (213, 4, 'expr 의 공백', '`expr 3 + 4` 와 `expr 3+4` 는 각각 무엇을 출력할까요? 곱셈은 어떻게 쓸까요?', 'expr 은 연산자 앞뒤를 인자로 나눠 봐요.', NULL, NULL, '[]', 'choice', '["둘 다 `7` 을 출력하고 곱셈은 `expr 7 * 3` 으로 쓴다", "`expr 3 + 4` 는 오류가 나고 `expr 3+4` 는 `7` 이다", "둘 다 `3+4` 를 출력한다", "`expr 3 + 4` 는 `7`, `expr 3+4` 는 계산하지 않고 `3+4` 를 그대로 출력한다. 곱셈은 셸이 `*` 를 해석하지 않도록 `expr 7 \\\\* 3` 처럼 쓴다"]', 3, '요즘은 `$((3+4))` 를 더 많이 씁니다.', NULL, NULL, NULL, NULL),
  (213, 5, 'read 로 나누기', '`read a b <<< "one two three"` 를 하면 `a` 와 `b` 에는 각각 무엇이 들어갈까요? 단어가 모자라면 남는 변수는요?', '마지막 변수가 나머지를 모두 받아요.', NULL, NULL, '[]', 'choice', '["`a` 는 `one`, `b` 는 `two` 이고 `three` 는 버려진다", "`a` 는 `one two three`, `b` 는 비어 있다", "`a` 는 `one`, `b` 는 나머지 전부인 `two three` 이다. 단어가 모자라면 남는 변수는 빈 값이 된다", "단어 수가 변수보다 많으면 오류가 난다"]', 2, '`IFS=: read u p rest` 처럼 구분 문자를 바꿀 수 있습니다.', NULL, NULL, NULL, NULL),
  (213, 6, 'read -r', '`read r <<< ''a\\nb''` 와 `read -r r <<< ''a\\nb''` 를 하면 `r` 은 각각 무엇일까요?', '-r 은 백슬래시를 그대로 두는 옵션이에요.', NULL, NULL, '[]', 'choice', '["둘 다 `a\\\\nb` 이다", "`-r` 이 없으면 백슬래시가 사라져 `anb`, `-r` 을 쓰면 `a\\\\nb` 가 그대로 들어간다", "`-r` 이 없으면 줄이 나뉘어 `a` 만 들어간다", "둘 다 `anb` 이다"]', 1, '경로나 정규식을 읽을 때는 보통 `read -r` 을 씁니다.', NULL, NULL, NULL, NULL),
  (213, 7, 'type, command -v, which', '`type -t cd` 와 `type -t ls` 는 각각 무엇을 출력할까요? 없는 명령에 `command -v nosuchcmd` 를 하면요?', 'type 은 명령의 종류를 알려 줘요.', NULL, NULL, '[]', 'choice', '["`cd` 는 `builtin`, `ls` 는 `file` 이 출력된다. 없는 명령에 `command -v` 를 하면 아무것도 출력하지 않고 종료 코드 `1` 이다", "`cd` 는 `file`, `ls` 는 `builtin` 이 출력된다", "두 명령 모두 `file` 이 출력된다", "`command -v nosuchcmd` 는 `not found` 를 출력하고 종료 코드 `0` 이다"]', 0, '함수를 정의하고 `type -t` 를 하면 `function` 이 출력됩니다.', NULL, NULL, NULL, NULL),
  (213, 8, 'export 와 자식 프로세스', '`V=local1` 을 만든 뒤 `bash -c ''echo "[$V]"''` 를 하면 무엇이 보일까요? `export V` 를 한 뒤에는요? `W=once bash -c ...` 처럼 앞에 붙이면요?', 'export 해야 자식에게 전달돼요.', NULL, NULL, '[]', 'choice', '["`export` 전에도 `[local1]` 이 보인다", "`export V` 를 해도 자식에게는 전달되지 않는다", "`W=once` 를 앞에 붙이면 부모 셸에도 계속 남는다", "`export` 전에는 자식 프로세스에서 비어 있어 `[]` 이고, `export V` 후에는 `[local1]` 이다. 명령 앞에 `W=once` 를 붙이면 그 명령에서만 보이고 부모 셸에는 남지 않는다"]', 3, '`export -n V` 를 하면 export 가 해제되어 자식에게 전달되지 않습니다.', NULL, NULL, NULL, NULL),
  (213, 9, 'ls 정렬 옵션', '`ls -t`, `ls -S`, `ls -r` 은 각각 어떤 순서로 보여 줄까요?', '시간, 크기, 거꾸로예요.', NULL, NULL, '[]', 'choice', '["`-t` 는 이름순, `-S` 는 작은 것부터, `-r` 은 재귀 출력이다", "`-t` 는 오래된 것부터, `-S` 는 이름순, `-r` 은 무작위이다", "`-t` 는 수정 시간이 최근인 것부터, `-S` 는 크기가 큰 것부터, `-r` 은 기본 순서를 거꾸로 보여 준다. `-tr`, `-Sr` 처럼 합치면 반대 순서가 된다", "`-t` 는 타입별, `-S` 는 소유자별, `-r` 은 읽기 전용 파일만이다"]', 2, '`ls -R` 은 하위 폴더까지 재귀로 보여 줍니다.', NULL, NULL, NULL, NULL),
  (213, 10, 'ls -d', '폴더 `sub1`, `sub2` 와 파일이 섞인 곳에서 `ls -d */` 를 하면 무엇이 나올까요? `ls -d sub1` 은 폴더 안 내용을 보여 줄까요?', '-d 는 폴더 안이 아니라 폴더 자신을 보여 줘요.', NULL, NULL, '[]', 'choice', '["파일과 폴더가 모두 나오고 폴더는 `/` 가 붙지 않는다", "`sub1/ sub2/` 처럼 폴더만 나온다. `ls -d sub1` 은 안의 내용이 아니라 `sub1` 이라는 폴더 자신만 보여 준다", "`ls -d sub1` 은 `sub1` 안의 파일 목록을 보여 준다", "`-d` 는 폴더를 삭제하는 옵션이다"]', 1, '`ls -ld sub1` 처럼 자세히 보면 맨 앞 글자가 `d` 로 나옵니다.', NULL, NULL, NULL, NULL),
  (213, 11, 'sort -k 와 -n', '`b 10`, `a 2`, `c 33` 줄을 `sort -k2` 로 정렬하면 어떤 순서일까요? `sort -k2 -n` 으로 하면요?', '-k2 는 두 번째 칸이 기준이에요.', NULL, NULL, '[]', 'choice', '["`-k2` 만 쓰면 글자 순서라 `b 10`, `a 2`, `c 33`, `-n` 을 함께 쓰면 숫자 순서라 `a 2`, `b 10`, `c 33` 이다", "`-k2` 만 써도 `a 2`, `b 10`, `c 33` 이다", "`-k2 -n` 은 `c 33`, `b 10`, `a 2` 이다", "`-k2` 는 첫 번째 칸을 기준으로 정렬한다"]', 0, '쉼표로 나뉜 파일은 `sort -t, -k2 -n` 처럼 구분자를 `-t` 로 정합니다.', NULL, NULL, NULL, NULL),
  (213, 12, 'cp -i 와 -n', '이미 있는 `t1` 에 `cp t2 t1` 을 하면 어떻게 될까요? `-i` 를 붙이면, `-n` 을 붙이면요?', '-i 는 묻고, -n 은 덮어쓰지 않아요.', NULL, NULL, '[]', 'choice', '["그냥 `cp` 도 항상 덮어쓰기 전에 묻는다", "`-n` 은 묻지 않고 항상 덮어쓴다", "`-i` 는 덮어쓰지 않고 `t1.bak` 으로 백업한다", "그냥 `cp t2 t1` 은 묻지 않고 덮어쓴다. `-i` 는 `overwrite ''t1''?` 라고 물어 `n` 이면 그대로 두고, `-n` 은 묻지 않고 덮어쓰지 않는다"]', 3, '`mv -i`, `mv -n`, `rm -i` 도 같은 방식으로 묻거나 막습니다.', NULL, NULL, NULL, NULL),
  (213, 13, 'nl 과 cat -n', '`a`, 빈 줄, `b` 세 줄에 `nl` 을 하면 번호가 어떻게 붙을까요? `cat -n` 은요?', 'nl 은 기본으로 빈 줄에 번호를 안 붙여요.', NULL, NULL, '[]', 'choice', '["`nl` 도 빈 줄에 번호를 붙여 `b` 는 3 이다", "`cat -n` 은 빈 줄에 번호를 붙이지 않는다", "`nl` 은 빈 줄에는 번호를 붙이지 않아 `a` 가 1, `b` 가 2 이고, `cat -n` 은 빈 줄에도 번호를 붙여 `a` 가 1, 빈 줄이 2, `b` 가 3 이다", "둘 다 번호를 붙이지 않는다"]', 2, '`nl -b a` 를 쓰면 빈 줄에도 번호가 붙습니다.', NULL, NULL, NULL, NULL),
  (213, 14, 'readlink 와 realpath', '`link` 가 `r1/r2` 를 가리키는 심볼릭 링크일 때 `readlink link` 와 `readlink -f link` 는 각각 무엇을 출력할까요?', '-f 는 끝까지 따라가 절대 경로로 보여 줘요.', NULL, NULL, '[]', 'choice', '["둘 다 절대 경로를 출력한다", "`readlink link` 는 링크가 가리키는 값인 `r1/r2` 만 보여 주고, `readlink -f link` 는 끝까지 따라가 절대 경로를 보여 준다. 링크가 아닌 일반 파일에 `readlink` 를 하면 아무것도 출력하지 않고 종료 코드 `1` 이다", "`readlink link` 는 `r1/r2` 안의 파일 내용을 보여 주고 `-f` 는 링크를 지운다", "`readlink` 는 링크를 만드는 명령이라 아무것도 출력하지 않는다"]', 1, '`realpath link` 도 같은 절대 경로를 보여 줍니다.', NULL, NULL, NULL, NULL),
  (213, 15, '지역 변수 선언', '함수 안에서만 쓰이는 **지역 변수를 만드는** 키워드를 채우세요.', '"지역의"를 뜻하는 영어예요.', NULL, NULL, '[]', 'fill', '["local", "private", "var", "my"]', NULL, '이 키워드가 없으면 전역 변수가 바뀝니다.', '[0]', 'f() { {0} x=inner; }', NULL, NULL),
  (213, 16, '나머지 구하기', '`$(( ))` 안에서 **나머지를 구하는** 연산자를 채우세요.', '퍼센트 기호예요.', NULL, NULL, '[]', 'fill', '["%", "//", "mod", "rem"]', NULL, '결과는 `1` 입니다.', '[0]', 'echo $(( 7 {0} 3 ))', NULL, NULL),
  (213, 17, '백슬래시 그대로 읽기', '`read` 가 **백슬래시를 그대로 두고 읽게 하는** 옵션을 채우세요.', '"raw"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-r", "-raw", "-b", "-x"]', NULL, '경로를 읽을 때 자주 씁니다.', '[0]', 'read {0} line', NULL, NULL),
  (213, 18, '명령의 종류만 보기', '`type` 에서 **명령의 종류(builtin, file 등)만 한 단어로 보여 주는** 옵션을 채우세요.', '"type"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-t", "-k", "-w", "-y"]', NULL, '`cd` 는 `builtin` 이 출력됩니다.', '[0]', 'type {0} cd', NULL, NULL),
  (213, 19, 'export 해제', 'export 한 변수의 **export 를 해제하는** 옵션을 채우세요.', '"no"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-n", "-d", "-u", "-r"]', NULL, '해제하면 자식 프로세스에 전달되지 않습니다.', '[0]', 'export {0} V', NULL, NULL),
  (213, 20, '큰 파일부터 정렬', '`ls` 에서 **크기가 큰 파일부터 보여 주는** 옵션을 채우세요.', '"Size"의 대문자예요.', NULL, NULL, '[]', 'fill', '["-S", "--size-sort", "--big", "-Y"]', NULL, '`-Sr` 은 작은 것부터 보여 줍니다.', '[0]', 'ls {0}', NULL, NULL),
  (213, 21, '폴더 자신만 보기', '`ls` 에서 **폴더 안이 아니라 폴더 자신만 보여 주는** 옵션을 채우세요.', '"directory"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-d", "-D", "-f", "-q"]', NULL, '폴더만 골라 볼 때 `*/` 와 함께 씁니다.', '[0]', 'ls {0} */', NULL, NULL),
  (213, 22, '두 번째 칸으로 정렬', '쉼표로 나뉜 파일을 **두 번째 칸 기준으로 정렬하는** 옵션을 채우세요.', '"key"의 첫 글자와 칸 번호예요.', NULL, NULL, '[]', 'fill', '["-k2", "--col=2", "--field=2", "-c2"]', NULL, '`-n` 은 숫자 순서로 정렬합니다.', '[0]', 'sort -t, {0} -n data.csv', NULL, NULL),
  (213, 23, '덮어쓰기 전에 묻기', '`cp` 가 **덮어쓰기 전에 묻게 하는** 옵션을 채우세요.', '"interactive"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-i", "--ask", "--confirm", "-y"]', NULL, '`n` 을 입력하면 덮어쓰지 않습니다.', '[0]', 'cp {0} t2 t1', NULL, NULL),
  (213, 24, '빈 줄에도 번호', '빈 줄에는 번호를 안 붙이는 **줄 번호 명령** 을 채우세요. `-b a` 를 붙이면 빈 줄에도 번호가 붙습니다.', '"number lines"의 앞 두 글자예요.', NULL, NULL, '[]', 'fill', '["nl", "cat", "wc", "tac"]', NULL, '`cat -n` 은 기본으로 빈 줄에도 번호를 붙입니다.', '[0]', '{0} -b a file.txt', NULL, NULL),
  (213, 25, '비는 폴더 함께 지우기', '`rmdir` 에서 **상위 폴더까지 비어 있으면 함께 지우는** 옵션을 채우세요.', '"parents"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-p", "-r", "-R", "-f"]', NULL, '폴더가 비어 있지 않으면 `Directory not empty` 오류가 납니다.', '[0]', 'rmdir {0} e2/in', NULL, NULL),
  (213, 26, '함수 정의하고 호출하기', '셸 함수를 만들어 호출하고 종료 코드를 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '정의 → 호출 → 종료 코드 → 종류 확인 순서예요.', NULL, NULL, '[]', 'order', '["`greet() { echo \\"hi $1\\"; return 3; }` 로 함수를 정의한다", "`greet bob` 으로 호출해 `hi bob` 이 출력되는지 본다", "바로 `echo $?` 를 해서 `return` 한 `3` 이 나오는지 확인한다", "`type greet` 로 `greet is a function` 이 나오는지 확인한다"]', NULL, '함수는 호출하기 전에 정의되어 있어야 합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (213, 27, '변수를 자식 프로세스에 넘기기', '변수가 자식 프로세스에 전달되는지 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 확인 → export → 다시 확인 → 해제 순서예요.', NULL, NULL, '[]', 'order', '["`V=local1` 로 변수를 만든다", "`bash -c ''echo \\"[$V]\\"''` 가 `[]` 로 비어 있는지 확인한다", "`export V` 후 같은 명령이 `[local1]` 을 출력하는지 확인한다", "`export -n V` 후 다시 비어 있는지 확인한다"]', NULL, '`W=once bash -c ...` 처럼 앞에 붙이면 그 명령에서만 보입니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (213, 28, '두 파일을 키로 합치기', '첫 칸의 키로 두 파일을 합치는 `join` 의 순서입니다. 순서에 맞게 놓아 보세요.', '정렬 확인 → join → 한쪽만 있는 줄 포함 → 한쪽에만 있는 줄 순서예요.', NULL, NULL, '[]', 'order', '["두 파일의 첫 칸이 정렬되어 있는지 확인하고 아니면 `sort` 로 정렬한다", "`join j1 j2` 로 키가 양쪽에 있는 줄만 합친 `1 apple red`, `3 fig green` 을 확인한다", "`join -a1 j1 j2` 로 `j1` 에만 있는 `2 pear` 도 함께 나오는지 본다", "`join -v1 j1 j2` 로 `j1` 에만 있는 `2 pear` 만 나오는지 확인한다"]', NULL, '정렬되지 않은 파일은 `is not sorted` 경고가 나고 결과가 어긋납니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (213, 29, '빈 폴더 지우기', '폴더를 안전하게 지우는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 비지 않아 실패 → -p 로 지우기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`mkdir -p e2/in` 으로 안쪽 폴더까지 만든다", "`rmdir e2` 가 `Directory not empty` 오류로 실패하는지 본다", "`rmdir -p e2/in` 으로 안쪽부터 상위 폴더까지 함께 지운다", "`ls e2` 가 `No such file or directory` 오류를 내는지 확인한다"]', NULL, '내용이 있는 폴더는 `rm -r` 로 지웁니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
